import re

class _Rules(Rules):
    DOSE = __DOSE__

    def filter_observation(self, obs, env_state):
        if self.DOSE == 0:
            return obs
        text = obs.text
        data = dict(obs.data) if isinstance(obs.data, dict) else {}
        cmds = list(data.get('admissible_commands') or [])

        # Does the policy currently hold the cellphone?
        holding = 'cellphone' in text and ('pick up the cellphone' in text or 'carrying' in text and 'cellphone' in text)

        if not holding:
            # Remove the premature desklamp action until the cellphone is held.
            cmds = [c for c in cmds if not re.search(r'use\s+desklamp', c)]
            # Stronger dose: also trim repetitive look/examine of the current spot.
            if self.DOSE >= 0.5:
                cmds = [c for c in cmds if c not in ('look', 'examine desk 1')]

            hint = ("\n\n[goal support] You have not found the cellphone yet. "
                    "Search the room's surfaces and containers (armchair, beds, dressers, drawers) for a cellphone, "
                    "take it, then return to the desklamp.")
            if self.DOSE >= 0.5:
                hint += " Do not turn on the desklamp until you are holding the cellphone."
            text = text.rstrip() + hint

        data['admissible_commands'] = cmds
        return Observation(text=text, data=data)

