class _Rules(Rules):
    DOSE = __DOSE__

    def filter_action(self, action, env_state):
        if self.DOSE == 0:
            return action
        cmd = (action.kwargs or {}).get('text', '') if action.kwargs else ''
        obs_text = env_state.obs_text or ''
        holding = 'cellphone' in obs_text and ('pick up the cellphone' in obs_text or 'carrying' in obs_text and 'cellphone' in obs_text)

        if not holding and re.search(r'use\s+desklamp', cmd):
            return Blocked(reason="You don't have the cellphone yet. Search the room for the cellphone and take it first.")

        if self.DOSE >= 0.5:
            if cmd in ('look', 'examine desk 1'):
                return Blocked(reason="You've already checked here. Go search other surfaces and containers for the cellphone.")

        return action

