class _Rules(Rules):
    DOSE = __DOSE__

    def filter_observation(self, obs, env_state):
        if self.DOSE == 0:
            return obs
        adms = list(obs.data.get('admissible_commands', []))
        clean_cmds = [a for a in adms if a.startswith('clean potato')]
        if not clean_cmds:
            return obs
        text = obs.text
        if self.DOSE >= 0.5:
            rest = [a for a in adms if a not in clean_cmds]
            adms = clean_cmds + rest
        prefix = 'GOAL SUB-STEP: clean the potato before putting it away.'
        if prefix not in text:
            text = text.replace('Admissible commands:', prefix + ' Admissible commands:')
        new_obs = Observation(text=text, data=dict(obs.data))
        new_obs.data['admissible_commands'] = adms
        return new_obs

import re

class _Rules(Rules):
    DOSE = __DOSE__

    def _subgoal_reminder(self, obs_text, dose):
        hint = "Remember: you need to FIND and TAKE a pillow, then USE the desklamp while holding the pillow."
        if dose <= 0:
            return obs_text
        # Split off the task header and append the reminder right after it.
        if 'Admissible commands:' in obs_text:
            body, adm = obs_text.split('Admissible commands:', 1)
            marker = '\n\n[HINT] ' + hint
            return body + marker + '\n\nAdmissible commands:' + adm
        return obs_text + '\n\n[HINT] ' + hint

    def filter_observation(self, obs, env_state):
        dose = self.DOSE
        if dose <= 0:
            return obs
        text = obs.text
        data = dict(obs.data) if obs.data is not None else {}
        cmds = list(data.get('admissible_commands') or [])
        new_text = self._subgoal_reminder(text, dose)

        # Boost salience of pillow-related commands: move 'go to bed 1' and
        # 'take pillow' to the front of the admissible list.
        if cmds:
            pillow_pref = [c for c in cmds if 'take pillow' in c or 'take pillow 1' in c]
            bed_pref = [c for c in cmds if re.search(r'go to bed 1\b', c)]
            rest = [c for c in cmds if c not in pillow_pref and c not in bed_pref]
            if dose >= 0.5:
                cmds = pillow_pref + bed_pref + rest
            elif dose > 0:
                cmds = bed_pref + pillow_pref + rest
            data['admissible_commands'] = cmds

        # Also annotate the rendered text with a marker on the pillow command.
        if dose > 0:
            for c in cmds:
                if 'take pillow' in c and ('>>' not in new_text):
                    new_text = new_text.replace(c, '>> ' + c + ' <<', 1)
                    break
        return Observation(text=new_text, data=data)

