class _Rules(Rules):
    DOSE = __DOSE__

    def filter_observation(self, obs, env_state):
        d = self.DOSE
        if d <= 0:
            return obs
        text = obs.text
        hints = []
        if d >= 0.34:
            hints.append("Hint: you need to find the newspaper first.")
        if d >= 0.67:
            hints.append("Hint: take the newspaper and bring it to the desklamp, then use the desklamp.")
        if hints:
            marker = "\n\nAdmissible commands:"
            if marker in text:
                text = text.replace(marker, "\n\n" + "\n".join(hints) + marker)
            else:
                text = text + "\n\n" + "\n".join(hints)
        return Observation(text=text, data=obs.data)

import re

class _Rules(Rules):
    DOSE = __DOSE__

    def filter_observation(self, obs, env_state):
        d = self.DOSE
        if d <= 0:
            return obs
        data = obs.data
        cmds = list(data.get("admissible_commands", [])) if isinstance(data, dict) else []
        if not cmds:
            return obs
        def key(c):
            m = re.match(r"go to sidetable (\d+)", c)
            if not m:
                return (1, c)
            n = int(m.group(1))
            # sidetable 1 hosts the desklamp; prefer the others for exploration
            if n == 1:
                return (2, c)
            return (0, c)
        new_cmds = sorted(cmds, key=key)
        limit = max(1, int(round(d * 6)))
        # ensure at least a few non-sidetable1 go-commands are front-loaded
        go_others = [c for c in new_cmds if re.match(r"go to sidetable (?!1\b)\d+", c)]
        rest = [c for c in new_cmds if c not in go_others]
        new_cmds = go_others[:limit] + rest
        new_data = dict(data)
        new_data["admissible_commands"] = new_cmds
        text = obs.text
        marker = "\n\nAdmissible commands:"
        if marker in text:
            text = text.split(marker)[0] + marker + " " + ", ".join(new_cmds)
        return Observation(text=text, data=new_data)

class _Rules(Rules):
    DOSE = __DOSE__

    def filter_action(self, action, env_state):
        if DOSE == 0:
            return action
        text = (action.kwargs or {}).get('text', '')
        cmds = list(env_state.admissible_commands)
        holding = any(c.startswith('cool lettuce') or c.startswith('move lettuce') for c in cmds)
        if holding:
            return action

        blocked_prefixes = []
        if DOSE >= 0.34:
            blocked_prefixes += ['open cabinet', 'open drawer']
        if DOSE >= 0.67:
            blocked_prefixes += ['open fridge', 'examine cabinet', 'examine drawer', 'examine fridge']
        if DOSE >= 0.9:
            blocked_prefixes += ['go to cabinet', 'go to drawer']

        for p in blocked_prefixes:
            if text.startswith(p):
                return Blocked(reason='find and take the lettuce first')
        return action
